def can_chain(dominoes):
    """Return a chain of all dominoes whose ends match, or None if impossible.

    A valid chain uses every domino exactly once (each may be flipped),
    has matching ends between adjacent dominoes, and its first and last
    ends match each other.
    """

    def backtrack(remaining, chain, first):
        if not remaining:
            if not chain:
                return []
            return chain if chain[-1][1] == first else None

        last = chain[-1][1] if chain else None
        for i, (a, b) in enumerate(remaining):
            rest = remaining[:i] + remaining[i + 1:]
            if chain:
                if a == last:
                    result = backtrack(rest, chain + [(a, b)], first)
                    if result is not None:
                        return result
                if b == last and b != a:
                    result = backtrack(rest, chain + [(b, a)], first)
                    if result is not None:
                        return result
            else:
                for orientation in ((a, b), (b, a)):
                    result = backtrack(rest, chain + [orientation], orientation[0])
                    if result is not None:
                        return result
        return None

    return backtrack(list(dominoes), [], None)

